using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public sealed class HotelVipLevelProfile
{
    private HotelVipLevelProfile() { }
    public Guid HotelVipLevelProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public int LevelNumber { get; private set; } public string? WelcomeBenefit { get; private set; } public string? AmenityBenefit { get; private set; } public bool AllowUpgrade { get; private set; } public decimal DiscountPercent { get; private set; } public int PriorityScore { get; private set; } public string? NotificationChannels { get; private set; } public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelVipLevelProfile Create(PropertyId propertyId, string code, string name, int levelNumber, string? welcomeBenefit, string? amenityBenefit, bool allowUpgrade, decimal discountPercent, int priorityScore, string? notificationChannels, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, levelNumber, discountPercent, priorityScore, from, to); return new() { HotelVipLevelProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = code.Trim().ToUpperInvariant(), Name = name.Trim(), LevelNumber = levelNumber, WelcomeBenefit = Normalize(welcomeBenefit), AmenityBenefit = Normalize(amenityBenefit), AllowUpgrade = allowUpgrade, DiscountPercent = discountPercent, PriorityScore = priorityScore, NotificationChannels = Normalize(notificationChannels), EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, int levelNumber, string? welcomeBenefit, string? amenityBenefit, bool allowUpgrade, decimal discountPercent, int priorityScore, string? notificationChannels, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId)
    { Validate(code, name, levelNumber, discountPercent, priorityScore, from, to); Code = code.Trim().ToUpperInvariant(); Name = name.Trim(); LevelNumber = levelNumber; WelcomeBenefit = Normalize(welcomeBenefit); AmenityBenefit = Normalize(amenityBenefit); AllowUpgrade = allowUpgrade; DiscountPercent = discountPercent; PriorityScore = priorityScore; NotificationChannels = Normalize(notificationChannels); EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; } private static void Validate(string code, string name, int level, decimal discount, int priority, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_VIP_LEVEL_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_VIP_LEVEL_NAME_REQUIRED"); if (level < 1 || level > 100) throw new ArgumentException("HOTEL_VIP_LEVEL_NUMBER_INVALID"); if (discount < 0 || discount > 100) throw new ArgumentException("HOTEL_VIP_LEVEL_DISCOUNT_INVALID"); if (priority < 0 || priority > 10000) throw new ArgumentException("HOTEL_VIP_LEVEL_PRIORITY_INVALID"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_VIP_LEVEL_EFFECTIVE_RANGE_INVALID"); } private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}
